This Adds a module to load and run runtime plugins in the `apollo-collaboration-server`. Apollo plugins are based on JBrowse plugins, and a simple example looks like this:

```ts
import { ApolloPlugin, ApolloPluginManager } from 'apollo-common'

export default class ApolloFirstPlugin extends ApolloPlugin {
  name = 'ApolloFirstPlugin'

  apolloInstall(pluginManager: ApolloPluginManager) {
    pluginManager.addToExtensionPoint(
      'GetAssembliesOperation-transformResults',
      async (results) => {
        console.log('in plugin')
        console.log(await results)
        return results
      },
    )
  }
}
```

Any operation can have its results intercepted and modified by using the `<operationName>-transformResults` extension point.

